      resetVariantForm();

      // Reload product to show new/updated variant
      const updated = await getJson(
        `${apiBase}/v1/products/${editingProduct.id}`,
      );

      setEditingProduct(updated);
      setProducts((prev) =>
        prev.map((p) => (p.id === editingProduct.id ? updated : p)),
      );
